-- dim.dim_opr_date_f 日期维度（1 行 = 1 天），2023-01-01 ~ 2028-12-31 共 2192 天
-- 由 scripts/dim_date/gen_dim_opr_date_f.py 生成（改范围：--start / --end），非分区全量覆盖；字段顺序与字典一致
-- 节假日来自国务院历年放假安排，农历来自香港天文台对照表；寒暑假、旺淡季为默认运营规则，见脚本 vacation_type / season_type
-- 估算：2028 年国务院放假安排未公布，按法定假日估算（逢周末顺延补休、不含调休上班），公布后补进脚本 HOLIDAYS 重跑
INSERT OVERWRITE TABLE dim.dim_opr_date_f     -- 整表覆盖写入
SELECT
  date_code,                                  -- 日期
  date_no,                                    -- 日期
  CAST(year_no AS INT) AS year_no,            -- 年
  CAST(quarter_no AS INT) AS quarter_no,      -- 季度
  CAST(month_no AS INT) AS month_no,          -- 月
  CAST(week_of_year_no AS INT) AS week_of_year_no,  -- ISO 周序号
  CAST(weekday_no AS INT) AS weekday_no,      -- 星期几
  weekday_mask_code,                          -- 星期位值
  CAST(weekend_type AS INT) AS weekend_type,  -- 是否周末
  CAST(holiday_type AS INT) AS holiday_type,  -- 日期类型
  holiday_name,                               -- 节假日名称
  CAST(vacation_type AS INT) AS vacation_type,  -- 是否寒暑假
  CAST(season_type AS INT) AS season_type,    -- 旺淡季
  week_start_date,                            -- 所在自然周周一日期
  month_start_date,                           -- 所在自然月第一天
  CAST(half_year_no AS INT) AS half_year_no,  -- 半年
  quarter_start_date,                         -- 所在季度第一天
  year_start_date,                            -- 所在年第一天
  holiday_period_code,                        -- 所属节假日区间编码
  CAST(holiday_day_no AS INT) AS holiday_day_no,  -- 节假日第 N 天（从 1 开始）
  lunar_date_code,                            -- 农历日期
  last_year_same_day_date,                    -- 同比对齐日
  DATE_FORMAT(CURRENT_TIMESTAMP(), 'yyyy-MM-dd HH:mm:ss') AS etl_time  -- ETL 加载时间
